INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-listening-03','LISTENING-03','Luyện nghe · Đề 03','listening','Luyện nghe',45,'published',1,'Đề luyện luyện nghe số 03 do Nhà Hán Ngữ biên soạn phục vụ tự học và tự đánh giá.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-listening-03-q01','seed-listening-03',1,'listening_tts','Theo câu vừa nghe, thời gian được nhắc đến là khi nào?','Nội dung nghe: “张老师说明天三点半在咖啡店见面。” Thông tin cần nhận diện trực tiếp là “三点半”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'张老师说明天三点半在咖啡店见面。',datetime('now')),
('seed-listening-03-q02','seed-listening-03',2,'listening_tts','Theo câu vừa nghe, hoạt động chính là gì?','Nội dung nghe: “小王说明天七点在地铁站复习中文。” Thông tin cần nhận diện trực tiếp là “复习中文”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'小王说明天七点在地铁站复习中文。',datetime('now')),
