INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-listening-04','LISTENING-04','Luyện nghe · Đề 04','listening','Luyện nghe',45,'published',1,'Đề luyện luyện nghe số 04 do Nhà Hán Ngữ biên soạn phục vụ tự học và tự đánh giá.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-listening-04-q01','seed-listening-04',1,'listening_tts','Theo câu vừa nghe, thời gian được nhắc đến là khi nào?','Nội dung nghe: “小王说明天四点在教室参加活动。” Thông tin cần nhận diện trực tiếp là “四点”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'小王说明天四点在教室参加活动。',datetime('now')),
('seed-listening-04-q02','seed-listening-04',2,'listening_tts','Theo câu vừa nghe, hoạt động chính là gì?','Nội dung nghe: “李明说明天两点在图书馆一起吃饭。” Thông tin cần nhận diện trực tiếp là “一起吃饭”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'李明说明天两点在图书馆一起吃饭。',datetime('now')),
('seed-listening-04-q03','seed-listening-04',3,'listening_tts','Theo câu vừa nghe, địa điểm được nhắc đến là đâu?','Nội dung nghe: “安娜说明天六点在学校门口见面。” Thông tin cần nhận diện trực tiếp là “学校门口”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'安娜说明天六点在学校门口见面。',datetime('now')),
('seed-listening-04-q04','seed-listening-04',4,'listening_tts','Theo câu vừa nghe, thời gian được nhắc đến là khi nào?','Nội dung nghe: “小林说明天三点半在咖啡店复习中文。” Thông tin cần nhận diện trực tiếp là “三点半”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'小林说明天三点半在咖啡店复习中文。',datetime('now')),
