INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-listening-05','LISTENING-05','Luyện nghe · Đề 05','listening','Luyện nghe',45,'published',1,'Đề luyện luyện nghe số 05 do Nhà Hán Ngữ biên soạn phục vụ tự học và tự đánh giá.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-listening-05-q01','seed-listening-05',1,'listening_tts','Theo câu vừa nghe, thời gian được nhắc đến là khi nào?','Nội dung nghe: “李明说明天六点在学校门口复习中文。” Thông tin cần nhận diện trực tiếp là “六点”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'李明说明天六点在学校门口复习中文。',datetime('now')),
('seed-listening-05-q02','seed-listening-05',2,'listening_tts','Theo câu vừa nghe, hoạt động chính là gì?','Nội dung nghe: “安娜说明天三点半在咖啡店讨论作业。” Thông tin cần nhận diện trực tiếp là “讨论作业”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'安娜说明天三点半在咖啡店讨论作业。',datetime('now')),
