INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-listening-17','LISTENING-17','Luyện nghe · Đề 17','listening','Luyện nghe',45,'published',1,'Đề luyện luyện nghe số 17 do Nhà Hán Ngữ biên soạn phục vụ tự học và tự đánh giá.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-listening-17-q01','seed-listening-17',1,'listening_tts','Theo câu vừa nghe, thời gian được nhắc đến là khi nào?','Nội dung nghe: “小林说明天两点在图书馆讨论作业。” Thông tin cần nhận diện trực tiếp là “两点”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'小林说明天两点在图书馆讨论作业。',datetime('now')),
('seed-listening-17-q02','seed-listening-17',2,'listening_tts','Theo câu vừa nghe, hoạt động chính là gì?','Nội dung nghe: “张老师说明天六点在学校门口参加活动。” Thông tin cần nhận diện trực tiếp là “参加活动”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'张老师说明天六点在学校门口参加活动。',datetime('now')),
('seed-listening-17-q03','seed-listening-17',3,'listening_tts','Theo câu vừa nghe, địa điểm được nhắc đến là đâu?','Nội dung nghe: “小王说明天三点半在咖啡店一起吃饭。” Thông tin cần nhận diện trực tiếp là “咖啡店”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'小王说明天三点半在咖啡店一起吃饭。',datetime('now')),
('seed-listening-17-q04','seed-listening-17',4,'listening_tts','Theo câu vừa nghe, thời gian được nhắc đến là khi nào?','Nội dung nghe: “李明说明天七点在地铁站见面。” Thông tin cần nhận diện trực tiếp là “七点”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'李明说明天七点在地铁站见面。',datetime('now')),
('seed-listening-17-q05','seed-listening-17',5,'listening_tts','Theo câu vừa nghe, hoạt động chính là gì?','Nội dung nghe: “安娜说明天四点在教室复习中文。” Thông tin cần nhận diện trực tiếp là “复习中文”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'安娜说明天四点在教室复习中文。',datetime('now')),
('seed-listening-17-q06','seed-listening-17',6,'listening_tts','Theo câu vừa nghe, địa điểm được nhắc đến là đâu?','Nội dung nghe: “小林说明天两点在图书馆讨论作业。” Thông tin cần nhận diện trực tiếp là “图书馆”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'小林说明天两点在图书馆讨论作业。',datetime('now')),
('seed-listening-17-q07','seed-listening-17',7,'listening_tts','Theo câu vừa nghe, thời gian được nhắc đến là khi nào?','Nội dung nghe: “张老师说明天六点在学校门口参加活动。” Thông tin cần nhận diện trực tiếp là “六点”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'张老师说明天六点在学校门口参加活动。',datetime('now')),
