INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-listening-20','LISTENING-20','Luyện nghe · Đề 20','listening','Luyện nghe',45,'published',1,'Đề luyện luyện nghe số 20 do Nhà Hán Ngữ biên soạn phục vụ tự học và tự đánh giá.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
