('seed-listening-20-q01','seed-listening-20',1,'listening_tts','Theo câu vừa nghe, thời gian được nhắc đến là khi nào?','Nội dung nghe: “李明说明天六点在学校门口复习中文。” Thông tin cần nhận diện trực tiếp là “六点”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'李明说明天六点在学校门口复习中文。',datetime('now')),
('seed-listening-20-q02','seed-listening-20',2,'listening_tts','Theo câu vừa nghe, hoạt động chính là gì?','Nội dung nghe: “安娜说明天三点半在咖啡店讨论作业。” Thông tin cần nhận diện trực tiếp là “讨论作业”. Người học nên nghe toàn câu trước, sau đó tập trung vào từ khóa chỉ thời gian, địa điểm hoặc hành động.',NULL,NULL,0,1,'安娜说明天三点半在咖啡店讨论作业。',datetime('now')),
